/*selectMasterMdAmMakerManageRegPopList*/ SELECT ROWNUM AS NO, C.CODE, C.TEXT1, C.TEXT3, C.TEXT5, C.TEXT6, C.ADD_DATE, DECODE(C.TYPE,'M104',(SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE ='M001' AND CODE = C.TEXT3),'') AS ORIGIN, C.TEXT7, (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE ='M070' AND COD.CODE = C.TEXT7) AS MG_TEXT FROM ICOMCOD1 C WHERE TYPE = 'M104' AND FLAG = 'Y'
AND C.CODE = #{st_code}
ORDER BY C.ADD_DATE
